insert into public.translation_dictionary(namespace,source_key,translations) values ('ui','Partial provider cost estimate (USD)','{"en":"Partial provider cost estimate (USD)","fr":"Estimation partielle des coûts fournisseurs (USD)"}'),('ui','Priced calls','{"en":"Priced calls","fr":"Appels dont le coût est calculable"}'),('ui','Partial estimates only. Missing units and invoice adjustments are excluded.','{"en":"Partial estimates only. Missing units and invoice adjustments are excluded.","fr":"Estimations partielles seulement. Les unités manquantes et ajustements de facturation sont exclus."}'),('ui','Open official Replicate billing and balance','{"en":"Open official Replicate billing and balance","fr":"Consulter la facturation et le solde Replicate"}') on conflict(namespace,source_key) do nothing;